import { IUser } from '@apps/Users/@services/users.service';

import { IBaseUserDTO } from '../@services/authService';
import { IUserPhone, IUserPhoneDTO } from '../@types/user.types';

export const mapBackUserPhoneToFront = (data: IUserPhoneDTO): IUserPhone => ({
  id: +data.id,
  phone: data.phone,
  is_send_sms: +data.is_send_sms === 1,
  is_contact: +data.is_contact === 1,
  sms_api_key: data.sms_api_key,
});

export const mapFrontUserPhoneToBack = (data: IUserPhone): IUserPhoneDTO => ({
  id: data.id.toString(),
  phone: data.phone,
  is_send_sms: data.is_send_sms ? '1' : '0',
  is_contact: data.is_contact ? '1' : '0',
  sms_api_key: data.sms_api_key,
});

export const mapBaseUserToFront = (backData: IBaseUserDTO): IUser => {
  return {
    id: +backData.id,
    name: backData.name,
    surname: backData.surname,
    photo: backData.photo_50,
  };
};
